const scrollFadeContent=document.getElementById("scroll-fade-content"),cards=scrollFadeContent.querySelectorAll(".card"),nextButtons=scrollFadeContent.querySelectorAll(".next-button");let cardPosition=1;function ShowNextCard(){this.removeEventListener("click",ShowNextCard);const card=cards[cardPosition];card.style.display="block",card.scrollIntoView({behavior:"smooth",block:"start"});const progressBar=GetProgressBar(cards[cardPosition-1]);CheckProgressBar(progressBar),cardPosition++}nextButtons.forEach(Button=>{Button.addEventListener("click",ShowNextCard)});const CheckProgressBar=ProgressBar=>{const bar=ProgressBar.querySelector(".progress-bar"),unchecked=ProgressBar.querySelector(".end-point-unchecked"),checked=ProgressBar.querySelector(".end-point-checked");unchecked.style.display="none",checked.style.display="block",bar.classList.add("show")},GetProgressBar=Card=>Card.querySelector(".progress-bar-container");